    51  /* Create a new (empty) frame */
    52  blosc2_frame_s* frame_new(const char* urlpath) {
    53    blosc2_frame_s* new_frame = calloc(1, sizeof(blosc2_frame_s));
    54    if (urlpath != NULL) {
    55      char* new_urlpath = malloc(strlen(urlpath) + 1);  // + 1 for the trailing NULL
    56      new_frame->urlpath = strcpy(new_urlpath, urlpath);
    57    }
    58    return new_frame;
    59  }
