    63  int frame_free(blosc2_frame_s* frame) {
    64
    65    if (frame->cframe != NULL && !frame->avoid_cframe_free) {
    66      free(frame->cframe);
    67    }
    68
    69    if (frame->coffsets != NULL) {
    70      free(frame->coffsets);
    71    }
    72
    73    if (frame->urlpath != NULL) {
    74      free(frame->urlpath);
    75    }
    76
    77    free(frame);
    78
    79    return 0;
