    83  void *new_header_frame(blosc2_schunk *schunk, blosc2_frame_s *frame) {
    84    if (frame == NULL) {
    85      return NULL;
    86    }
    87    uint8_t* h2 = calloc(FRAME_HEADER_MINLEN, 1);
    88    uint8_t* h2p = h2;
    89
    90    // The msgpack header starts here
    91    *h2p = 0x90;  // fixarray...
    92    *h2p += 14;   // ...with 13 elements
    93    h2p += 1;
    94
    95    // Magic number
    96    *h2p = 0xa0 + 8;  // str with 8 elements
    97    h2p += 1;
    98    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
    99      return NULL;
   100    }
   101    strcpy((char*)h2p, "b2frame");
   102    h2p += 8;
   103
   104    // Header size
   105    *h2p = 0xd2;  // int32
   106    h2p += 1 + 4;
   107    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   108      return NULL;
   109    }
   110
   111    // Total frame size
   112    *h2p = 0xcf;  // uint64
   113    // Fill it with frame->len which is known *after* the creation of the frame (e.g. when updating the header)
   114    int64_t flen = frame->len;
   115    to_big(h2 + FRAME_LEN, &flen, sizeof(flen));
   116    h2p += 1 + 8;
   117    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   118      return NULL;
   119    }
   120
   121    // Flags
   122    *h2p = 0xa0 + 4;  // str with 4 elements
   123    h2p += 1;
   124    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   125      return NULL;
   126    }
   127
   128    // General flags
   129    *h2p = BLOSC2_VERSION_FRAME_FORMAT;  // version
   130    *h2p += 0x10;  // 64-bit offsets.  We only support this for now.
   131    h2p += 1;
   132    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   133      return NULL;
   134    }
   135
   136    // Frame type
   137    // We only support contiguous and sparse directories frames currently
   138    *h2p = frame->sframe ? 1 : 0;
   139    h2p += 1;
   140    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   141      return NULL;
   142    }
   143
   144    // Codec flags
   145    *h2p = schunk->compcode;
   146    *h2p += (schunk->clevel) << 4u;  // clevel
   147    h2p += 1;
   148    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   149      return NULL;
   150    }
   151
   152    // Reserved flags
   153    *h2p = 0;
   154    h2p += 1;
   155    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   156      return NULL;
   157    }
   158
   159    // Uncompressed size
   160    *h2p = 0xd3;  // int64
   161    h2p += 1;
   162    int64_t nbytes = schunk->nbytes;
   163    to_big(h2p, &nbytes, sizeof(nbytes));
   164    h2p += 8;
   165    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   166      return NULL;
   167    }
   168
   169    // Compressed size
   170    *h2p = 0xd3;  // int64
   171    h2p += 1;
   172    int64_t cbytes = schunk->cbytes;
   173    to_big(h2p, &cbytes, sizeof(cbytes));
   174    h2p += 8;
   175    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   176      return NULL;
   177    }
   178
   179    // Type size
   180    *h2p = 0xd2;  // int32
   181    h2p += 1;
   182    int32_t typesize = schunk->typesize;
   183    to_big(h2p, &typesize, sizeof(typesize));
   184    h2p += 4;
   185    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   186      return NULL;
   187    }
   188
   189    // Block size
   190    *h2p = 0xd2;  // int32
   191    h2p += 1;
   192    int32_t blocksize = schunk->blocksize;
   193    to_big(h2p, &blocksize, sizeof(blocksize));
   194    h2p += 4;
   195    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   196      return NULL;
   197    }
   198
   199    // Chunk size
   200    *h2p = 0xd2;  // int32
   201    h2p += 1;
   202    int32_t chunksize = schunk->chunksize;
   203    to_big(h2p, &chunksize, sizeof(chunksize));
   204    h2p += 4;
   205    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   206      return NULL;
   207    }
   208
   209    // Number of threads for compression
   210    *h2p = 0xd1;  // int16
   211    h2p += 1;
   212    int16_t nthreads = (int16_t)schunk->cctx->nthreads;
   213    to_big(h2p, &nthreads, sizeof(nthreads));
   214    h2p += 2;
   215    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   216      return NULL;
   217    }
   218
   219    // Number of threads for decompression
   220    *h2p = 0xd1;  // int16
   221    h2p += 1;
   222    nthreads = (int16_t)schunk->dctx->nthreads;
   223    to_big(h2p, &nthreads, sizeof(nthreads));
   224    h2p += 2;
   225    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   226      return NULL;
   227    }
   228
   229    // The boolean for variable-length metalayers
   230    *h2p = (schunk->nvlmetalayers > 0) ? (uint8_t)0xc3 : (uint8_t)0xc2;
   231    h2p += 1;
   232    if (h2p - h2 >= FRAME_HEADER_MINLEN) {
   233      return NULL;
   234    }
   235
   236    // The space for FRAME_FILTER_PIPELINE
   237    *h2p = 0xd8;  //  fixext 16
   238    h2p += 1;
   239    if (BLOSC2_MAX_FILTERS > FRAME_FILTER_PIPELINE_MAX) {
   240      return NULL;
   241    }
   242    // Store the filter pipeline in header
   243    uint8_t* mp_filters = h2 + FRAME_FILTER_PIPELINE + 1;
   244    uint8_t* mp_meta = h2 + FRAME_FILTER_PIPELINE + 1 + FRAME_FILTER_PIPELINE_MAX;
   245    int nfilters = 0;
   246    for (int i = 0; i < BLOSC2_MAX_FILTERS; i++) {
   247      if (schunk->filters[i] != BLOSC_NOFILTER) {
   248        mp_filters[nfilters] = schunk->filters[i];
   249        mp_meta[nfilters] = schunk->filters_meta[i];
   250        nfilters++;
   251      }
   252    }
   253    *h2p = (uint8_t)nfilters;
   254    h2p += 1;
   255    h2p += 16;
   256    if (h2p - h2 != FRAME_HEADER_MINLEN) {
   257      return NULL;
   258    }
   259
   260    int32_t hsize = FRAME_HEADER_MINLEN;
   261
   262    // Now, deal with metalayers
   263    int16_t nmetalayers = schunk->nmetalayers;
   264    if (nmetalayers < 0 || nmetalayers > BLOSC2_MAX_METALAYERS) {
   265      return NULL;
   266    }
   267
   268    // Make space for the header of metalayers (array marker, size, map of offsets)
   269    h2 = realloc(h2, (size_t)hsize + 1 + 1 + 2 + 1 + 2);
   270    h2p = h2 + hsize;
   271
   272    // The msgpack header for the metalayers (array_marker, size, map of offsets, list of metalayers)
   273    *h2p = 0x90 + 3;  // array with 3 elements
   274    h2p += 1;
   275
   276    // Size for the map (index) of offsets, including this uint16 size (to be filled out later on)
   277    *h2p = 0xcd;  // uint16
   278    h2p += 1 + 2;
   279
   280    // Map (index) of offsets for optional metalayers
   340      h2p = h2 + current_header_len;
   341      // Store the serialized contents for this metalayer
   342      *h2p = 0xc6;  // bin32
   343      h2p += 1;
   344      to_big(h2p, &(metalayer->content_len), sizeof(metalayer->content_len));
   345      h2p += 4;
   346      memcpy(h2p, metalayer->content, metalayer->content_len);  // buffer, no need to swap
   347      h2p += metalayer->content_len;
   348      // Update the offset now that we know it
   349      to_big(h2 + offtooff[nmetalayer], &current_header_len, sizeof(current_header_len));
   350      current_header_len += 1 + 4 + metalayer->content_len;
   351    }
   352    free(offtooff);
   353    hsize = (int32_t)(h2p - h2);
   354    if (hsize != current_header_len) {  // sanity check
   355      return NULL;
   356    }
   357
   358    // Set the length of the whole header now that we know it
   359    to_big(h2 + FRAME_HEADER_LEN, &hsize, sizeof(hsize));
   360
   361    return h2;
   362  }
