   365  int get_header_info(blosc2_frame_s *frame, int32_t *header_len, int64_t *frame_len, int64_t *nbytes,
   366                      int64_t *cbytes, int32_t *blocksize, int32_t *chunksize, int32_t *nchunks,
   367                      int32_t *typesize, uint8_t *compcode, uint8_t *clevel, uint8_t *filters,
   368                      uint8_t *filters_meta) {
   369    uint8_t* framep = frame->cframe;
   370    uint8_t header[FRAME_HEADER_MINLEN];
   371
   372    if (frame->len <= 0) {
   373      return BLOSC2_ERROR_READ_BUFFER;
   374    }
   375
   376    if (frame->cframe == NULL) {
   377      size_t rbytes = 0;
   378      FILE* fp = NULL;
   379      if (frame->sframe) {
   380        fp = sframe_open_index(frame->urlpath, "rb");
   381      }
   382      else {
   383        fp = fopen(frame->urlpath, "rb");
   384      }
   385      if (fp != NULL) {
   386        rbytes = fread(header, 1, FRAME_HEADER_MINLEN, fp);
   387        fclose(fp);
   388      }
   389      (void) rbytes;
   390      if (rbytes != FRAME_HEADER_MINLEN) {
   391        return BLOSC2_ERROR_FILE_READ;
   392      }
   393      framep = header;
   394    }
   395
   396    // Consistency check for frame type
   397    uint8_t frame_type = framep[FRAME_TYPE];
   398    if (frame->sframe) {
   399      if (frame_type != FRAME_DIRECTORY_TYPE) {
   400        return BLOSC2_ERROR_FRAME_TYPE;
   401      }
   402    } else {
   403      if (frame_type != FRAME_CONTIGUOUS_TYPE) {
   404        return BLOSC2_ERROR_FRAME_TYPE;
   405      }
   406    }
   407
   408    // Fetch some internal lengths
   409    from_big(header_len, framep + FRAME_HEADER_LEN, sizeof(*header_len));
   410    from_big(frame_len, framep + FRAME_LEN, sizeof(*frame_len));
   411    from_big(nbytes, framep + FRAME_NBYTES, sizeof(*nbytes));
   412    from_big(cbytes, framep + FRAME_CBYTES, sizeof(*cbytes));
   413    from_big(blocksize, framep + FRAME_BLOCKSIZE, sizeof(*blocksize));
   414    from_big(chunksize, framep + FRAME_CHUNKSIZE, sizeof(*chunksize));
   415    if (typesize != NULL) {
   416      from_big(typesize, framep + FRAME_TYPESIZE, sizeof(*typesize));
   417    }
   418
   419    if (*header_len <= 0 || *header_len > *frame_len) {
   420      BLOSC_TRACE_ERROR("Header length is invalid or exceeds length of the frame.");
   421      return BLOSC2_ERROR_INVALID_HEADER;
   422    }
   423
   424    // Codecs
   425    uint8_t frame_codecs = framep[FRAME_CODECS];
   426    if (clevel != NULL) {
   427      *clevel = frame_codecs >> 4u;
   428    }
   429    if (compcode != NULL) {
   430      *compcode = frame_codecs & 0xFu;
   431    }
   432
   433    // Filters
   434    if (filters != NULL && filters_meta != NULL) {
   435      uint8_t nfilters = framep[FRAME_FILTER_PIPELINE];
   436      if (nfilters > BLOSC2_MAX_FILTERS) {
   437        BLOSC_TRACE_ERROR("The number of filters in frame header are too large for Blosc2.");
   438        return BLOSC2_ERROR_INVALID_HEADER;
   439      }
   440      uint8_t *filters_ = framep + FRAME_FILTER_PIPELINE + 1;
   441      uint8_t *filters_meta_ = framep + FRAME_FILTER_PIPELINE + 1 + FRAME_FILTER_PIPELINE_MAX;
   442      for (int i = 0; i < nfilters; i++) {
   443        filters[i] = filters_[i];
   444        filters_meta[i] = filters_meta_[i];
   445      }
   446    }
   447
   448    if (*nbytes > 0 && *chunksize > 0) {
   449      // We can compute the number of chunks only when the frame has actual data
   450      *nchunks = (int32_t) (*nbytes / *chunksize);
   451      if (*nbytes % *chunksize > 0) {
   452        if (*nchunks == INT32_MAX) {
   453          BLOSC_TRACE_ERROR("Number of chunks exceeds maximum allowed.");
   454          return BLOSC2_ERROR_INVALID_HEADER;
   455        }
  1490    new_storage->dparams = dparams;
  1491
  1492    return new_storage;
  1493  }
