  1496  /* Get a super-chunk out of a frame */
  1497  blosc2_schunk* frame_to_schunk(blosc2_frame_s* frame, bool copy) {
  1498    int32_t header_len;
  1499    int64_t frame_len;
  1500    int rc;
  1501    blosc2_schunk* schunk = calloc(1, sizeof(blosc2_schunk));
  1502    schunk->frame = (blosc2_frame*)frame;
  1503    rc = get_header_info(frame, &header_len, &frame_len, &schunk->nbytes,
  1504                         &schunk->cbytes, &schunk->blocksize,
  1505                         &schunk->chunksize, &schunk->nchunks, &schunk->typesize,
  1506                         &schunk->compcode, &schunk->clevel, schunk->filters,
  1507                         schunk->filters_meta);
  1508    if (rc < 0) {
  1509      BLOSC_TRACE_ERROR("Unable to get meta info from frame.");
  1510      blosc2_schunk_free(schunk);
  1511      return NULL;
  1512    }
  1513    int32_t nchunks = schunk->nchunks;
  1514    int64_t nbytes = schunk->nbytes;
  1515    (void) nbytes;
  1516    int64_t cbytes = schunk->cbytes;
  1517
  1518    // Compression and decompression contexts
  1519    blosc2_cparams *cparams;
  1520    blosc2_schunk_get_cparams(schunk, &cparams);
  1521    schunk->cctx = blosc2_create_cctx(*cparams);
  1522    blosc2_dparams *dparams;
  1523    blosc2_schunk_get_dparams(schunk, &dparams);
  1524    schunk->dctx = blosc2_create_dctx(*dparams);
  1525    blosc2_storage storage = {.contiguous = copy ? false : true};
  1526    schunk->storage = get_new_storage(&storage, cparams, dparams);
  1527    free(cparams);
  1528    free(dparams);
  1529
  1530    if (!copy) {
  1531      goto out;
  1532    }
  1533
  1534    // We are not attached to a frame anymore
  1535    schunk->frame = NULL;
  1536
  1537    if (nchunks == 0) {
  1538      goto out;
  1539    }
  1540
  1541    // Get the compressed offsets
  1542    int32_t coffsets_cbytes = 0;
  1543    uint8_t* coffsets = get_coffsets(frame, header_len, cbytes, &coffsets_cbytes);
  1544    if (coffsets == NULL) {
  1545      blosc2_schunk_free(schunk);
  1546      BLOSC_TRACE_ERROR("Cannot get the offsets for the frame.");
  1547      return NULL;
  1548    }
  1549
  1550    // Decompress offsets
  1551    blosc2_dparams off_dparams = BLOSC2_DPARAMS_DEFAULTS;
  1552    blosc2_context *dctx = blosc2_create_dctx(off_dparams);
  1553    int64_t* offsets = (int64_t *) malloc((size_t)nchunks * 8);
  1554    int32_t off_nbytes = blosc2_decompress_ctx(dctx, coffsets, coffsets_cbytes,
  1555                                               offsets, nchunks * sizeof(int64_t));
  1556    blosc2_free_ctx(dctx);
  1557    if (off_nbytes < 0) {
  1558      free(offsets);
  1559      blosc2_schunk_free(schunk);
  1560      BLOSC_TRACE_ERROR("Cannot decompress the offsets chunk.");
  1561      return NULL;
  1562    }
  1563
  1564    // We want the contiguous schunk, so create the actual data chunks (and, while doing this,
  1565    // get a guess at the blocksize used in this frame)
  1566    int64_t acc_nbytes = 0;
  1567    int64_t acc_cbytes = 0;
  1568    int32_t blocksize = 0;
  1569    int32_t chunk_nbytes;
  1570    int32_t chunk_cbytes;
  1690  }
