  1706  int get_coffset(blosc2_frame_s* frame, int32_t header_len, int64_t cbytes, int32_t nchunk, int64_t *offset) {
  1707    int32_t off_cbytes;
  1708    // Get the offset to nchunk
  1709    uint8_t *coffsets = get_coffsets(frame, header_len, cbytes, &off_cbytes);
  1710    if (coffsets == NULL) {
  1711      BLOSC_TRACE_ERROR("Cannot get the offset for chunk %d for the frame.", nchunk);
  1712      return BLOSC2_ERROR_DATA;
  1713    }
  1714
  1715    // Get the 64-bit offset
  1716    int rc = blosc2_getitem(coffsets, off_cbytes, nchunk, 1, offset, (int32_t)sizeof(int64_t));
  1717    if (rc < 0) {
  1718      BLOSC_TRACE_ERROR("Problems retrieving a chunk offset.");
  1719    } else if (*offset > frame->len) {
  1720      BLOSC_TRACE_ERROR("Cannot read chunk %d outside of frame boundary.", nchunk);
  1721      rc = BLOSC2_ERROR_READ_BUFFER;
  1722    }
  1723
  1724    return rc;
  1725  }
